function countQueenLayouts(n: number): number {
  const colOf: number[] = [];
  const safe = (row: number, c: number): boolean => {
    for (let r = 0; r < row; r++) {
      const d = row - r;
      if (colOf[r] === c || colOf[r] === c - d || colOf[r] === c + d) return false;
    }
    return true;
  };
  const go = (row: number): number => {
    if (row === n) return 1;
    let total = 0;
    for (let c = 0; c < n; c++) {
      if (!safe(row, c)) continue;
      colOf[row] = c;
      total += go(row + 1);
    }
    return total;
  };
  return go(0);
}

