function countQueenLayouts(n: number): number {
  const cols = new Set<number>(), diag = new Set<number>(), anti = new Set<number>();
  const go = (row: number): number => {
    if (row === n) return 1;
    let total = 0;
    for (let c = 0; c < n; c++) {
      if (cols.has(c) || diag.has(row - c) || anti.has(row + c)) continue;
      cols.add(c); diag.add(row - c); anti.add(row + c);
      total += go(row + 1);
      cols.delete(c); diag.delete(row - c); anti.delete(row + c);
    }
    return total;
  };
  return go(0);
}

