function countQueenLayouts(n: number): number {
  const full = (1 << n) - 1;
  const go = (cols: number, left: number, right: number): number => {
    if (cols === full) return 1;
    let total = 0;
    let free = full & ~(cols | left | right);
    while (free) {
      const bit = free & -free; // lowest free column
      free -= bit;
      total += go(cols | bit, ((left | bit) << 1) & full, (right | bit) >> 1);
    }
    return total;
  };
  return go(0, 0, 0);
}

